// #6e5ece (6a993d666cd36172db6e5ece) — AC3 «ממשק הניהול נתמך במלואו בדסקטופ ובמובייל במצב קריא». Кейс ADM-001.
// Только чтение — @prod-safe. Роль user (משתמש בית העסק, .qa/auth/user.json), как в проверке 14.10.
// Админка — только @desktop (урок L-20261014-5: телефон есть только у кандидата); узкие окна 390/768 — тем же Chrome.
import * as path from 'path';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user.json') });

const HASH = '#6a993d666cd36172db6e5ece';
const REPORT_ID = '7ade4110-48a9-4f1d-9835-b3ecb102cbcc'; // отчёт кандидата testim (QA-данные, тот же, что в business-background-gradient)
const PAGES = ['/', '/candidates', '/candidates/new', '/simulations', `/candidates/${REPORT_ID}/report`];

async function measure(page: import('@playwright/test').Page) {
  return page.evaluate(() => {
    const vw = window.innerWidth;
    const h1 = document.querySelector('h1');
    const r = h1?.getBoundingClientRect();
    return {
      vw,
      sw: document.documentElement.scrollWidth,
      bw: document.body.scrollWidth,
      dir: document.documentElement.getAttribute('dir'),
      h1: h1 ? { left: Math.round(r!.left), right: Math.round(r!.right), text: (h1.textContent || '').trim().slice(0, 40) } : null,
    };
  });
}

test.describe(`Админка — десктоп полностью, мобильная ширина читаема (${HASH})`, () => {
  for (const url of PAGES) {
    test(`${url}: 1440 без горизонтальной прокрутки; 768 и 390 — страница без горизонтальной прокрутки, заголовок целиком в окне, RTL @desktop @prod-safe ${HASH}`, async ({ page }) => {
      for (const w of [1440, 768, 390]) {
        await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
        if (w === 1440) {
          await page.goto(url);
          await expect(page).not.toHaveURL(/login|signin|auth/);
        }
        await expect(page.locator('h1').first()).toBeVisible({ timeout: 30_000 });
        const m = await measure(page);
        // Источник: AC3; факт 14.10 — 1440 без прокрутки, 390/768 страница без прокрутки (длинные строки — внутри карточки).
        expect(m.sw, `${url} @${w}: html.scrollWidth`).toBeLessThanOrEqual(m.vw);
        expect(m.bw, `${url} @${w}: body.scrollWidth`).toBeLessThanOrEqual(m.vw);
        expect(m.dir, `${url}: html dir`).toBe('rtl');
        expect(m.h1, `${url}: нет h1`).not.toBeNull();
        expect(m.h1!.left, `${url} @${w}: заголовок «${m.h1!.text}» за левым краем`).toBeGreaterThanOrEqual(-1);
        expect(m.h1!.right, `${url} @${w}: заголовок «${m.h1!.text}» за правым краем`).toBeLessThanOrEqual(m.vw + 1);
      }
    });
  }
});
